 22	 default UUID getAvatarId(Product product) {
 23	 if (product.getProductImages() != null) {
 24	 return product.getProductImages().stream()
 25	 .filter(ProductImage::getAvatar)
 26	 .map(ProductImage::getFileId)
 27	 .findFirst()
 28	 .orElse(null);
 29	 }
 30	 return null;
 31	 }
