 17	 public ResponseException(String message, Throwable cause, ResponseError error) {
 18	 this(message, cause, error, (Object) null);
 19	 }
 20	
 21	 public ResponseException(String message, Throwable cause, ResponseError error, Object... params) {
 22	 super(Objects.nonNull(message) ? MessageFormat.format(message, params) : error.getMessage(), cause);
 23	 this.error = error;
 24	 this.params = params == null ? new Object[0] : params;
 25	 }
 26	
 27	 public ResponseException(ResponseError error, Object... params) {
